"""Archive creation helpers for the ouch-compatible command line."""
import bz2
import gzip
import io
import lzma
import os
import tarfile
import zipfile
from pathlib import Path

ALIASES = {
    "tgz": ("tar", "gz"), "tbz": ("tar", "bz"), "tbz2": ("tar", "bz2"),
    "txz": ("tar", "xz"), "tlzma": ("tar", "lzma"), "tlz4": ("tar", "lz4"),
    "tsz": ("tar", "sz"), "tzst": ("tar", "zst"), "tlz": ("tar", "lz"),
    "cbt": ("tar",), "cbz": ("zip",), "epub": ("zip",), "cb7": ("7z",),
}

def formats_for(path, fmt=None):
    if fmt:
        exts = [x.lower().lstrip(".") for x in fmt.split(".") if x]
    else:
        name = Path(path).name.lower()
        exts = name.split(".")[1:] if "." in name else []
    if len(exts) == 1 and exts[0] in ALIASES:
        exts = list(ALIASES[exts[0]])
    return exts

def _collect(inputs, follow=False):
    result=[]
    for raw in inputs:
        p=Path(raw)
        if p.is_dir():
            result.append((p, p.name))
            for root, dirs, files in os.walk(p, followlinks=follow):
                dirs.sort(); files.sort()
                rp=Path(root)
                result.extend((rp/d, str((rp/d).as_posix())) for d in dirs)
                result.extend((rp/f, str((rp/f).as_posix())) for f in files)
        else:
            result.append((p, p.name))
    return result

def _tar(inputs, follow=False):
    buf=io.BytesIO()
    with tarfile.open(fileobj=buf, mode="w", format=tarfile.PAX_FORMAT) as tf:
        for p, arc in _collect(inputs, follow):
            if not p.is_symlink() or follow:
                tf.add(p, arcname=arc, recursive=False)
            else:
                info=tarfile.TarInfo(arc); info.type=tarfile.SYMTYPE; info.linkname=os.readlink(p)
                tf.addfile(info)
    return buf.getvalue()

def compress(inputs, output, *, fmt=None, level=None, fast=False, slow=False, follow=False, quiet=False):
    """Create output; returns (success, message)."""
    fmts=formats_for(output, fmt)
    if not fmts:
        return False, f'[ERROR] Cannot compress to "{output}"\n - You must supply the compression format\n\nhint: Try adding supported extensions (see --help):\nhint:   ouch compress <FILES>... {output}.tar.gz\nhint:   ouch compress <FILES>... {output}.zip\nhint: \nhint: Alternatively, you can overwrite this option by using the \'--format\' flag:\nhint:   ouch compress <FILES>... {output} --format tar.gz'
    supported={"tar","zip","gz","bz","bz2","xz","lzma"}
    if any(f not in supported for f in fmts):
        bad=next(f for f in fmts if f not in supported)
        return False, f'[ERROR] Unsupported extension "{bad}"'
    try:
        if fmts[0] == "tar":
            data=_tar(inputs, follow)
            fmts=fmts[1:]
        elif fmts[0] == "zip":
            buf=io.BytesIO()
            with zipfile.ZipFile(buf,"w",compression=zipfile.ZIP_DEFLATED,compresslevel=level) as z:
                for p, arc in _collect(inputs, follow):
                    if p.is_dir():
                        z.writestr(arc.rstrip("/")+"/", b"")
                    elif p.is_file(): z.write(p,arc)
            data=buf.getvalue(); fmts=fmts[1:]
        elif fmts[0] in ("gz","bz","bz2","xz","lzma") and len(inputs)==1:
            data=Path(inputs[0]).read_bytes()
        else:
            data=_tar(inputs, follow)
        for f in fmts:
            if f=="gz": data=gzip.compress(data, compresslevel=max(0,min(9,level if level is not None else (1 if fast else 9 if slow else 6))), mtime=0)
            elif f in ("bz","bz2"): data=bz2.compress(data, compresslevel=max(1,min(9,level if level is not None else 9 if slow else 1 if fast else 9)))
            elif f=="xz": data=lzma.compress(data, preset=max(0,min(9,level if level is not None else 9 if slow else 0 if fast else 6)))
            elif f=="lzma": data=lzma.compress(data, format=lzma.FORMAT_ALONE, preset=max(0,min(9,level if level is not None else 6)))
        Path(output).write_bytes(data)
        return True, ""
    except Exception as e:
        return False, f"[ERROR] {e}"
"""Standard-library decompression operations for the ouch-compatible CLI."""
from __future__ import annotations
import bz2, gzip, lzma, os, shutil, tarfile, zipfile
from pathlib import Path, PurePosixPath

_SINGLE = {'.gz': gzip.decompress, '.bz2': bz2.decompress, '.bz': bz2.decompress,
           '.xz': lzma.decompress, '.lzma': lzma.decompress}
_ALIASES = {'.tgz': '.tar.gz', '.tbz': '.tar.bz', '.tbz2': '.tar.bz2', '.txz': '.tar.xz', '.tlzma': '.tar.lzma'}

def _strip_name(name: str) -> tuple[str, str]:
    low = name.lower()
    for alias, expanded in _ALIASES.items():
        if low.endswith(alias):
            return name[:-len(alias)] + expanded[len(alias):], expanded
    for ext in ('.tar.gz','.tar.bz2','.tar.bz','.tar.xz','.tar.lzma','.tar'):
        if low.endswith(ext): return name[:-len(ext)], ext
    return os.path.splitext(name)[0], os.path.splitext(name)[1].lower()

def _safe_join(root: Path, member: str) -> Path:
    # Archive member paths are interpreted relative to destination, never outside it.
    clean = PurePosixPath(member.replace('\\', '/'))
    parts = [p for p in clean.parts if p not in ('/', '..', '.')]
    return root.joinpath(*parts)

def _extract_tar(tf: tarfile.TarFile, root: Path) -> list[tuple[str,int]]:
    items=[]
    for m in tf.getmembers():
        dest=_safe_join(root,m.name)
        if m.isdir():
            dest.mkdir(parents=True,exist_ok=True)
        elif m.isfile():
            dest.parent.mkdir(parents=True,exist_ok=True)
            src=tf.extractfile(m)
            if src:
                with src, open(dest,'wb') as out: shutil.copyfileobj(src,out)
            try: os.chmod(dest,m.mode & 0o777)
            except OSError: pass
            items.append((str(dest),m.size))
        elif m.issym():
            dest.parent.mkdir(parents=True,exist_ok=True)
            try: os.symlink(m.linkname,dest)
            except OSError: pass
    return items

def _extract_zip(zf: zipfile.ZipFile, root: Path) -> list[tuple[str,int]]:
    items=[]
    for m in zf.infolist():
        dest=_safe_join(root,m.filename)
        if m.is_dir(): dest.mkdir(parents=True,exist_ok=True); continue
        dest.parent.mkdir(parents=True,exist_ok=True)
        with zf.open(m) as src, open(dest,'wb') as out: shutil.copyfileobj(src,out)
        items.append((str(dest),m.file_size))
    return items

def decompress_one(filename: str, output_dir: str|None=None, here: bool=False) -> tuple[str,list[tuple[str,int]]]:
    src=Path(filename)
    data=src.read_bytes()
    base, ext=_strip_name(src.name)
    is_tar = ext.startswith('.tar') or tarfile.is_tarfile(src)
    if ext == '.zip' or zipfile.is_zipfile(src):
        root=Path(output_dir) if output_dir is not None else (Path('.') if here else Path(base))
        root.mkdir(parents=True,exist_ok=True)
        with zipfile.ZipFile(src) as zf: entries=_extract_zip(zf,root)
        return str(root),entries
    if is_tar:
        root=Path(output_dir) if output_dir is not None else (Path('.') if here else Path(base))
        root.mkdir(parents=True,exist_ok=True)
        with tarfile.open(src,'r:*') as tf: entries=_extract_tar(tf,root)
        return str(root),entries
    if ext in _SINGLE:
        outpath=Path(output_dir) / base if output_dir is not None else Path(base)
        if here and output_dir is None: outpath=Path(base)
        outpath.parent.mkdir(parents=True,exist_ok=True)
        decoded=_SINGLE[ext](data)
        # Chained stream compression: peel successive recognized extensions.
        remainder=Path(base).suffix.lower()
        while remainder in _SINGLE:
            decoded=_SINGLE[remainder](decoded)
            outpath=outpath.with_suffix('')
            remainder=outpath.suffix.lower()
        if decoded.startswith((b'PK\x03\x04',b'PK\x05\x06')):
            outpath.parent.mkdir(parents=True,exist_ok=True)
            with zipfile.ZipFile(__import__('io').BytesIO(decoded)) as zf: entries=_extract_zip(zf,outpath.parent)
            return str(outpath.parent),entries
        if len(decoded)>262 and decoded[257:262]==b'ustar':
            outpath.parent.mkdir(parents=True,exist_ok=True)
            with tarfile.open(fileobj=__import__('io').BytesIO(decoded),mode='r:*') as tf: entries=_extract_tar(tf,outpath.parent)
            return str(outpath.parent),entries
        outpath.write_bytes(decoded)
        return str(outpath),[(str(outpath),len(decoded))]
    raise ValueError(f"unsupported format: {filename}")

